-- Initial schema for the Tawafok marriage platform.
-- Public tables use RLS and are intended to be accessed by the server API
-- with SUPABASE_SERVICE_ROLE_KEY until narrower authenticated policies are reviewed.

create table if not exists public.members (
  id text primary key, nickname text not null default '', username text unique, real_name text not null default '', email text not null default '', phone text not null default '', whatsapp text not null default '', password text not null default '', gender text not null default '', birth_date text not null default '', age integer not null default 0, country text not null default '', city text not null default '', district text not null default '', nationality text not null default '', sect text not null default '', religion_level text not null default '', marital_status text not null default 'single', marital_label text not null default '', marriage_type text not null default 'announced', has_children boolean not null default false, children_count text not null default '', housing_type text not null default '', housing text not null default '', skin_color text not null default '', height integer not null default 0, weight integer not null default 0, health text not null default '', health_status text not null default '', smoking text not null default '', prayer text not null default '', ethnicity text not null default '', tribe text not null default '', education text not null default '', work_type text not null default '', job_title text not null default '', income_range text not null default '', bio text not null default '', about_partner text not null default '', p_country text not null default '', p_city text not null default '', p_nationality text not null default '', p_age_min text not null default '', p_age_max text not null default '', p_marital_status text not null default '', p_accept_children text not null default '', p_notes text not null default '', verified boolean not null default false, premium boolean not null default false, online boolean not null default false, last_active timestamptz not null default now(), match_score integer not null default 90, has_seriousness_badge boolean not null default false, plan text not null default 'free', pinned boolean not null default false, status text not null default 'active', status_reason text not null default '', status_by text not null default '', notes text not null default '', flagged boolean not null default false, source_type text not null default 'registered', import_batch_id text not null default '', import_office_name text not null default '', import_date text not null default '', import_notes text not null default '', is_profile_incomplete boolean not null default false, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.member_auth_links (auth_user_id uuid primary key, member_id text not null, email text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.admin_users (id text primary key, username text not null default 'admin', name text not null default '', email text not null unique, role text not null default 'admin', permissions jsonb not null default '{}'::jsonb, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.interest_requests (id bigint generated by default as identity primary key, sender_id text not null, receiver_id text not null, journey_stage text not null default 'sent', status text not null default 'sent', mediation_stage text not null default 'sent', message text not null default '', sender_paid boolean not null default false, receiver_paid boolean not null default false, sender_paid_at timestamptz, receiver_paid_at timestamptz, deadline_date timestamptz, decline_reason text, cancel_reason text, defer_date timestamptz, defer_by text, meeting_date timestamptz, meeting_notes text, contact_info text, contact_by text, guardian_phone text, guardian_name text, guardian_relation text, contact_time text, contact_note text, male_phone text, male_name text, male_relation text, male_contact_time text, male_contact_note text, male_pledged boolean not null default false, female_pledged boolean not null default false, sender_viewing_result text, sender_viewing_note text, receiver_viewing_result text, receiver_viewing_note text, evaluation_result text, evaluation_note text, frozen boolean not null default false, frozen_reason text, frozen_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.request_events (id bigint generated by default as identity primary key, request_id bigint not null, actor_id text, action text not null default '', payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.inquiry_messages (id text primary key, request_id text not null, sender_id text not null, message text not null default '', approved boolean not null default false, rejected boolean not null default false, moderated_by text, moderated_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.transactions (id bigint generated by default as identity primary key, member_id text not null default 'system', user_id text, request_id bigint, amount numeric not null default 0, type text not null default 'payment', plan_id text, description text not null default '', status text not null default 'pending', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.support_tickets (id bigint generated by default as identity primary key, user_id text not null default '', subject text not null default 'تذكرة دعم', message text not null default '', category text not null default 'استفسار عام', priority text not null default 'normal', status text not null default 'open', assigned_to text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.support_messages (id bigint generated by default as identity primary key, ticket_id bigint not null, sender text not null default 'user', text text not null default '', created_at timestamptz not null default now());
create table if not exists public.notifications (id bigint generated by default as identity primary key, user_id text not null, request_id bigint, type text not null default 'system', title text, message text not null default '', text text, read boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.verification_docs (id text primary key, member_id text not null, file_url text not null default '', file_name text not null default '', status text not null default 'pending', notes text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.settings (key text primary key, value text not null default '', updated_at timestamptz not null default now());
create table if not exists public.coupons (code text primary key, discount numeric not null default 0, discount_percent numeric, is_active boolean not null default true, uses_count integer not null default 0, expires_at timestamptz, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_logs (id bigint generated by default as identity primary key, actor_email text not null default '', action text not null default '', target_type text not null default '', target_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.rate_limits (key text primary key, count integer not null default 0, window_start timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.geo_countries (id bigint generated by default as identity primary key, name text not null unique, code text not null default '', flag text not null default '', created_at timestamptz not null default now());
create table if not exists public.geo_cities (id bigint generated by default as identity primary key, country text not null, name text not null, created_at timestamptz not null default now(), unique(country, name));
create table if not exists public.pending_cities (id text primary key, name text not null, country text not null default '', suggested_by text not null default '', suggested_by_id text not null default '', source text not null default 'register', status text not null default 'pending', rejection_reason text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.geo_nationalities (name text primary key, country text not null default '', gender text not null default 'both', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.geo_suggestions (id text primary key, kind text not null, name text not null, country text not null default '', suggested_by text not null default '', suggested_by_id text not null default '', source text not null default 'register', status text not null default 'pending', target_name text not null default '', target_country text not null default '', rejection_reason text not null default '', reviewer text, reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.exemption_requests (id text primary key, member_id text not null, reason text not null default '', status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.member_reports (id text primary key, reporter_id text not null, reporter_name text not null default '', reported_id text not null default '', reported_name text not null default '', reason text not null default '', status text not null default 'pending', category text, severity text, admin_notes text not null default '', action_log jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create index if not exists members_status_created_idx on public.members(status, created_at desc);
create index if not exists members_email_lower_idx on public.members(lower(email));
create index if not exists interest_requests_parties_idx on public.interest_requests(sender_id, receiver_id);
create index if not exists interest_requests_updated_idx on public.interest_requests(updated_at desc);
create index if not exists notifications_user_created_idx on public.notifications(user_id, created_at desc);
create index if not exists inquiry_messages_request_created_idx on public.inquiry_messages(request_id, created_at);
create index if not exists audit_logs_created_idx on public.audit_logs(created_at desc);

do $$ declare r record; begin
  for r in select tablename from pg_tables where schemaname = 'public' and tablename in ('members','member_auth_links','admin_users','interest_requests','request_events','inquiry_messages','transactions','support_tickets','support_messages','notifications','verification_docs','settings','coupons','audit_logs','rate_limits','geo_countries','geo_cities','pending_cities','geo_nationalities','geo_suggestions','exemption_requests','member_reports') loop
    execute format('alter table public.%I enable row level security', r.tablename);
    execute format('revoke all on table public.%I from anon, authenticated', r.tablename);
    execute format('grant all on table public.%I to service_role', r.tablename);
  end loop;
end $$;
grant usage, select on all sequences in schema public to service_role;
insert into storage.buckets (id, name, public) values ('verification-docs', 'verification-docs', true) on conflict (id) do nothing;
